const articleMatch = productUrl.match(/(?:catalog|nm)\/(\d+)/);
if (!articleMatch) return { error: "Invalid Link", url: productUrl };
const article = parseInt(articleMatch[1]);

// Math for folder structure
const vol = Math.floor(article / 100000);
const part = Math.floor(article / 1000);

