// This allows us to check multiple URLs at once and return the first success
async function findFirstWorkingUrl(urls, type = 'json') {
    const promises = urls.map(async (u) => {
        try {
            const res = await this.helpers.httpRequest({ 
                url: u.url, 
                method: 'GET', 
                headers: {
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                    'Referer': productUrl
                },
                json: true,
                timeout: 3000 // Fast timeout to speed up brute force
            });
            // Validation: API must have products, Image/JSON just needs 200 OK
            if (type === 'api' && (!res.data || !res.data.products || res.data.products.length === 0)) throw new Error("Empty API");
            return { ...res, _originUrl: u.url, _meta: u.meta };
        } catch (e) {
            throw e;
        }
    });

    try {
        // Promise.any returns the first successfully resolved promise
        return await Promise.any(promises);
    } catch (e) {
        return null;
    }
}

// --- STEP 1: BRUTE FORCE API (Find Product Data) ---
// We check multiple regions because some items are hidden in Moscow but visible in KZ
const dests = [
    { id: '-1257786', name: 'Moscow' },
    { id: '-1257466', name: 'Almaty (KZ)' }, // Your target
    { id: '-1257211', name: 'Minsk (BY)' },
    { id: '-59208', name: 'Bishkek (KG)' },
    { id: '-446116', name: 'Yerevan (AM)' }
];

const apiUrls = dests.map(d => ({
    url: `https://card.wb.ru/cards/v2/detail?appType=1&curr=kzt&dest=${d.id}&spp=30&nm=${article}`,
    meta: d.name
}));

let product = null;
let apiResult = await findFirstWorkingUrl.call(this, apiUrls, 'api');

if (apiResult && apiResult.data && apiResult.data.products) {
    product = apiResult.data.products[0];
}

// --- STEP 2: BRUTE FORCE HOST (Find Images) ---
// If we found the product in API, we might know the host. If not, scan standard baskets.
