let cardData = null;

// 2a. Generate list of likely baskets (Standard calc + neighbors)
// Standard logic often maps to specific ranges, but for robustness we check 01-20 and specific high ones like 30-40 for new items
const getBasketUrl = (num) => `https://basket-${num < 10 ? '0' + num : num}.wbbasket.ru`;

// We create a list of URLs to check for "card.json"
// We prioritize the calculated basket, then scan others if that fails
const calculatedBasketIndex = function(a) {
    const v = Math.floor(a / 100000);
    if (v <= 143) return 1; if (v <= 287) return 2; if (v <= 431) return 3; if (v <= 719) return 4;
    if (v <= 1007) return 5; if (v <= 1061) return 6; if (v <= 1115) return 7; if (v <= 1169) return 8;
    if (v <= 1313) return 9; if (v <= 1601) return 10; if (v <= 1655) return 11; if (v <= 1919) return 12;
    if (v <= 2045) return 13; if (v <= 2189) return 14; if (v <= 2405) return 15; if (v <= 2621) return 16;
    if (v <= 2837) return 17; if (v <= 3053) return 18; if (v <= 3269) return 19; if (v <= 3485) return 20;
    if (v <= 3701) return 21; if (v <= 3917) return 22; if (v <= 4133) return 23; if (v <= 4349) return 24;
    if (v <= 4565) return 25; if (v <= 4781) return 26; if (v <= 4997) return 27; if (v <= 5213) return 28;
    if (v <= 5429) return 29; if (v <= 5645) return 30; if (v <= 5861) return 31; if (v <= 6077) return 32;
    if (v <= 6293) return 33; if (v <= 6509) return 34; if (v <= 6725) return 35; if (v <= 6941) return 36;
    if (v <= 7157) return 37; if (v <= 7373) return 38; if (v <= 7589) return 39; if (v <= 7805) return 40;
    return 41; // Default fallback, but we will scan anyway
}(article);

// Prioritized list of baskets to check
let basketsToCheck = [calculatedBasketIndex]; 
// Add 01-75 to the list to be safe
for(let i=1; i<=75; i++) { if(!basketsToCheck.includes(i)) basketsToCheck.push(i); }

// Construct URLs to check for card.json (fastest way to verify host)
// We slice to check in batches to not overload n8n, but Promise.any handles concurrency well
const hostUrls = basketsToCheck.slice(0, 50).map(b => ({
    url: `${getBasketUrl(b)}/vol${vol}/part${part}/${article}/info/ru/card.json`,
    meta: getBasketUrl(b)
}));

const hostResult = await findFirstWorkingUrl.call(this, hostUrls, 'json');

if (hostResult) {
    cardData = hostResult;
    host = hostResult._meta;
}

// --- 3. COMPILE RESULTS ---

if (!product && !cardData) {
    return { error: "Product completely inaccessible (Blocked in all regions or invalid ID)", article };
}

// Determine photo count
let photoCount = 0;
if (product && product.pics) photoCount = product.pics;
else if (cardData && cardData.media && cardData.media.photo_count) photoCount = cardData.media.photo_count;
if (photoCount === 0) photoCount = 1;

// Construct Images
