    description: cardData?.description || "",
    price: finalPrice,
    currency: "KZT",
    rating: product?.reviewRating || 0,
    reviewsCount: product?.feedbacks || 0,
    totalImages: allImages.length,
    mainImageUrl: allImages[0] || null,
