    airtableAttachments: allImages.map(url => ({ url })),
    options: options,
    debug_found_in_region: apiResult?._meta || "None",
    debug_host_found: host || "None"
};

// === PREPARE GEMINI PAYLOAD WITH ALL IMAGES ===

return items.map(item => {
