    slide_number: slideData.slide_number,
    slide_type: slideData.slide_type,
    image_prompt: slideData.image_prompt,
    aspect_ratio: slideData.aspect_ratio,
    imageSize: "4K"
  };

  const finalPrompt = `${JSON.stringify(slideJSON, null, 2)}

[TECHNICAL REQUIREMENTS]
- Aspect Ratio: ${aspectRatio}
- Use the attached reference images to maintain product consistency
- Generate high quality professional image`;

  // 4. Build Gemini parts array - text first, then all images
  const parts = [{ text: finalPrompt }];

  // 5. Add ALL reference images to this slide
  imageList.forEach(base64 => {
    if (base64 && typeof base64 === 'string') {
      // Remove data URL prefix if present
      const cleanBase64 = base64.replace(/^data:image\/\w+;base64,/, '');

      parts.push({
        inline_data: {
          mime_type: "image/jpeg",
          data: cleanBase64
        }
      });
    }
  });

  // 6. Return Gemini request body
  return {
    json: {
      geminiBody: {
        contents: [{ parts: parts }],
        generationConfig: {
          responseModalities: ["TEXT", "IMAGE"]
        }
      },
      fileName: `slide_${slideNumber}`,
      slideNumber: slideNumber,
      imageCount: imageList.length
    }
  };
});

// Extract Image URLs from Webhook
const inputData = items[0].json.body;
let urls = $('Webhook').first().json.body.image_urls;

// Ensure it's an array
if (!Array.isArray(urls)) {
  if (typeof urls === 'string' && urls.length > 0) urls = [urls];
  else urls = [];
}

// Limit to 14 images
urls = urls.slice(0, 14);

// If no images, pass an empty item so flow doesn't break
if (urls.length === 0) return [{json: {url: ""}}];

return urls.map(url => ({ json: { url } }));

