// 1. Get raw content from AI node
const aiNode = $('data-to-js1').first().json;

let rawContent = "";

// Extract raw string from various possible structures
if (aiNode?.data && Array.isArray(aiNode.data) && aiNode.data.length > 0) {
  try {
    const firstItem = typeof aiNode.data[0] === 'string' 
      ? JSON.parse(aiNode.data[0]) 
      : aiNode.data[0];
    rawContent = firstItem.text || firstItem.content || JSON.stringify(firstItem);
  } catch (e) {
    rawContent = String(aiNode.data[0]);
  }
} else if (aiNode?.text) {
  rawContent = aiNode.text;
} else {
  rawContent = JSON.stringify(aiNode || {});
}

// 2. Clean JSON
function cleanAndExtractJSON(str) {
  if (typeof str !== 'string') str = JSON.stringify(str);

  str = str.replace(/```json\s*/gi, '').replace(/```\s*/g, '');

  const firstBrace = str.indexOf('{');
  const lastBrace = str.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    str = str.substring(firstBrace, lastBrace + 1);
  }

  return str.trim();
}

// 3. Parse JSON
function parseJSONSafe(rawStr) {
  const cleaned = cleanAndExtractJSON(rawStr);

  try {
    return JSON.parse(cleaned);
  } catch (e1) {
    try {
      const noTrailingCommas = cleaned.replace(/,\s*([\]}])/g, '$1');
      return JSON.parse(noTrailingCommas);
    } catch (e2) {
      return null;
    }
  }
}

let parsedData = parseJSONSafe(rawContent);

if (!parsedData) {
  return [{ 
    json: { 
      error: "JSON Parse Failed", 
      slide_number: 1,
      image_prompt: "Error parsing AI response"
    } 
  }];
}

