  slidesArray = parsedData.creatives;
} else if (Array.isArray(parsedData.thumbnails)) {
  slidesArray = parsedData.thumbnails;
} else if (Array.isArray(parsedData.ads_creatives)) {
  slidesArray = parsedData.ads_creatives;
} else if (parsedData.image_prompt) {
  slidesArray = [parsedData];
}

// 5. Normalize each slide
slidesArray = slidesArray.map((slide, index) => {
  let finalPrompt = "";

  if (typeof slide.image_prompt === 'string') {
    finalPrompt = slide.image_prompt;
  } else if (slide.image_prompt?.full_prompt) {
    finalPrompt = slide.image_prompt.full_prompt;
  } else if (slide.final_image_prompt) {
    finalPrompt = slide.final_image_prompt;
  } else if (typeof slide.image_prompt === 'object' && slide.image_prompt !== null) {
    // FIX: Catch complex nested objects and stringify them
    finalPrompt = JSON.stringify(slide.image_prompt);
