    slide_number: slide.slide_number || slide.creative_number || slide.version || index + 1,
    slide_type: slide.slide_type || slide.creative_name || slide.version_name || "SLIDE",
    image_prompt: finalPrompt,
    aspect_ratio: $('Webhook').first().json.body.aspect || "4:5"
  };
});

if (slidesArray.length === 0) {
  return [{ json: { error: "No slides found", slide_number: 1, image_prompt: "" } }];
}

return slidesArray.map(slide => ({ json: slide }));

