// Loop over all incoming items
return $input.all().map(item => {
  try {
    // 1. Get the raw text string. 
    // We access the deep path you provided: content -> parts -> 0 -> text
    const rawContent = item.json.content.parts[0].text;

    // 2. Clean the string.
    // The AI returns the data wrapped in markdown like ```json ... ```
    // We use Regex to remove "```json" and the closing "```"
    const cleanJsonString = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();

    // 3. Parse the string into a real JSON object
    const parsedData = JSON.parse(cleanJsonString);

    // 4. Return the clean data
    // We put the parsed data into the root of the item so it's easy to use in next nodes
    return {
      json: parsedData
    };

  } catch (error) {
    // Error handling in case the AI returned broken JSON
    return {
      json: {
        error: "Could not parse JSON",
        message: error.message,
        original_text: item.json.content ? item.json.content.parts[0].text : "No content found"
      }
    };
  }
});
